import { mapGetters } from 'vuex'
import { getByPage } from '@/api/xcnanr/deviceTerminalRecord'

export default {
  name: 'DeviceTerminalRecord',
  components: { },
  computed: { ...mapGetters(["permission", "userInfo", 'userDetail']) },
  props: {
    record: {
      type: Object,
      default(){
        return {
          id: '',
          compangyId: '',
          companyName: '',
          bastionId: '',
          bastionName: '',
          deviceName: '',
          ip: '',
          workerName: '',
          workerId: '',

        }
      }
    }
  },
  data() {
    return {
      dialogFlag: false,
      dialogTitle: '设备操作指令记录',
      dialogType: '',
      childDialogForm: {},
      sattusOptions: [],
      sourceOptions: [],

      selectionList: [], // 复选框
      searchForm: {
        pageNo: 1,
        pageSize: 10,
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false
    }
  },
  created() {
  },
  mounted() {
    this.setPageContentHeight()
    this.setTableHeight()
    this.getList()
  },
  watch: {
    'record.id': function () {
      this.queryEvent()
    }
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      // let bodyBox = document.getElementsByClassName('page_body')
      // this.tableHeight = (bodyBox[0].offsetHeight - 10) + 'px'
    },
    selectionChange(selection) {
      this.selectionList = selection.map(item => item.id)
    },
    queryEvent() {
      this.searchForm.pageNumber = 1;
      this.searchForm.pageSize = 10;
      this.getList()
    },
    resetEvent() {
      this.searchForm.command = undefined
      this.getList()
    },
    getList() {
      this.tableLoading = true
      this.searchForm.deviceRecordId = this.record.id
      getByPage(this.searchForm).then(res => {
        this.tableData = res.data.list
        this.total = res.data.total
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    tbClick(type) {
      this.$message.success(type)
    }
  }
}
